const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 256 256">${(icons[n]||icons.file).map(d=>`<path d="${d}"/>`).join('')}</svg>`;
const studentPages=[['overview','学习首页','home'],['progress','学习进度','chart'],['training','练车预约','calendar'],['my-bookings','我的训练','car'],['my-exams','考试信息','book'],['profile','个人资料','user']];
const adminPages=[['dashboard','教学概览','home'],['students','学员管理','users'],['hours','学时管理','clock'],['coaches','教练管理','user'],['vehicles','车辆管理','car'],['schedules','训练排班','calendar'],['bookings','练车预约','file'],['exams','考试管理','book'],['settings','科目规则','settings'],['logs','操作记录','file'],['profile','个人资料','user']];
const labels={active:['正常','good'],inactive:['已停用',''],maintenance:['维修中','warn'],open:['可预约','good'],booked:['待训练','blue'],completed:['已完成','good'],cancelled:['已取消',''],absent:['未到场','bad'],pending:['待核对','warn'],approved:['已核对','blue'],rejected:['需补充','bad'],passed:['已通过','good'],failed:['未通过','bad'],valid:['有效','good'],void:['已作废','']};
const badge=(s,label)=>`<span class="status ${labels[s]?.[1]||''}">${esc(label||labels[s]?.[0]||s)}</span>`;
const user=id=>state.students.find(x=>x.id===id)||{name:'学员',license:''};
const coach=id=>state.coaches.find(x=>x.id===id)||{name:'未分配',phone:'-',description:''};
const vehicle=id=>state.vehicles.find(x=>x.id===id)||{plate:'-',license:'',model:''};
const schedule=id=>state.schedules.find(x=>x.id===id);
const subject=id=>state.subjects.find(x=>x.id===id);
const hours=(uid,sid)=>state.hours.filter(x=>x.student_id===uid&&(!sid||x.subject_id===sid)&&x.status==='valid').reduce((n,x)=>n+x.minutes,0);
const hourText=n=>`${Number((n/60).toFixed(2))}`;
const hasPassed=(uid,sid)=>state.exams.some(e=>e.student_id===uid&&e.subject_id===sid&&e.status==='passed');
const stage=uid=>state.subjects.find(s=>!hasPassed(uid,s.id));
const pct=(n,total)=>Math.min(100,Math.round(n/total*100));
const addDay=(delta,base=state?.today)=>new Date(new Date(base+'T00:00:00Z').getTime()+delta*86400000).toISOString().slice(0,10);
const dateLabel=d=>d?`${Number(d.slice(5,7))}月${Number(d.slice(8,10))}日`:'待安排';
const greeting=()=>{const hour=Number(state.server_time.slice(11,13));return hour<11?'上午好':hour<14?'中午好':hour<18?'下午好':'晚上好';};
const weekLabel=d=>['周日','周一','周二','周三','周四','周五','周六'][new Date(d+'T12:00:00+08:00').getDay()];
const btn=(label,action,id='',kind='',extra='')=>`<button class="btn ${kind}" data-action="${action}" data-id="${esc(id)}" ${extra}>${label}</button>`;
const action=(label,name,id='',kind='')=>`<button class="inline-btn ${kind}" data-action="${name}" data-id="${esc(id)}">${label}</button>`;
const nav=(r,label,kind='')=>`<a class="btn ${kind}" href="#/${r}">${label}</a>`;
const logText=v=>String(v).replace(/：verify$/,"：已核对").replace(/：record-result$/,"：已同步外部成绩").replace(/：return$/,"：退回补充").replace(/：cancel$/,"：已撤回");
const paper=(title,body,extra='')=>`<section class="paper"><div class="paper-head"><h2>${title}</h2>${extra}</div>${body}</section>`;
const empty=(title='暂无记录',description='新的记录会显示在这里。',link='')=>`<div class="empty"><div class="empty-circle">${icon('file')}</div><h3>${esc(title)}</h3><p>${esc(description)}</p>${link}</div>`;
const table=(heads,rows)=>rows.length?`<div class="paper"><div class="table-scroll"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="table-count">共 ${rows.length} 条记录</div></div>`:`<div class="paper">${empty('没有符合条件的记录','调整筛选条件，或添加一条新记录。')}</div>`;
const heading=(title,desc,button='',eyebrow='')=>`<div class="page-heading"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1><p>${desc}</p></div>${button}</div>`;
const progressBar=(value,total)=>`<div class="bar"><span style="width:${pct(value,total)}%"></span></div>`;
const person=s=>`<div class="cell-person"><span class="avatar">${esc(s.name.slice(-2))}</span><div><div class="cell-title">${esc(s.name)}</div><div class="cell-sub">${esc(s.username||'')}</div></div></div>`;
const f=()=>filters[route]||(filters[route]={});
const matches=(value,q)=>!q||String(value).toLowerCase().includes(q.toLowerCase());
const options=(items,current,placeholder)=>`${placeholder?`<option value="">${placeholder}</option>`:''}${items.map(([v,t])=>`<option value="${esc(v)}" ${String(current)===String(v)?'selected':''}>${esc(t)}</option>`).join('')}`;
const subjectOptions=()=>state.subjects.map(s=>[s.id,s.name]);
const studentOptions=()=>state.students.filter(s=>s.status==='active').map(s=>[s.id,`${s.name} · ${s.username}`]);
const coachOptions=license=>state.coaches.filter(c=>c.status==='active'&&(!license||c.license.includes(license))).map(c=>[c.id,`${c.name} · ${c.license}`]);

async function api(path,{method='GET',body}={}) {
  const response=await fetch('/api/'+path,{method,headers:method==='GET'?{}:{'Content-Type':'application/json','X-Requested-With':'DrivingSchool'},...(body!==undefined?{body:JSON.stringify(body)}:{})});
  const result=await response.json();if(!response.ok){const error=new Error(result.error||'请求失败');error.status=response.status;throw error;}return result;
}
function toast(message,error=false){clearTimeout(toastTimer);const el=$('#toast');el.textContent=message;el.className='visible'+(error?' error':'');toastTimer=setTimeout(()=>el.className='',4000);}
async function refresh(){state=await api('state');render();}
function login(){state=null;document.title='登录 · 启程驾校';app.innerHTML=`<main class="login"><section class="login-story"><div class="brand"><span class="brand-symbol">启</span><span>启程驾校<small>QICHENG DRIVING SCHOOL</small></span></div><div class="login-story-content"><div class="eyebrow">每一程，都有进步</div><h1>从第一次握住方向盘，<br>到从容出发。</h1><p>学习进度、训练安排、考试登记。<br>你的学车旅程，在这里有序向前。</p><div class="login-road"><span>科目一</span><span>科目二</span><span>科目三</span><span>科目四</span></div></div><div class="login-story-footer">学员学习进度与预约管理平台</div></section><section class="login-panel"><form id="login-form" class="login-form"><h2>欢迎回来</h2><p>登录账号，继续你的学车旅程。</p><div class="form-error" role="alert"></div><div class="field"><label for="username">账号</label><input id="username" name="username" placeholder="请输入账号" autocomplete="username" required maxlength="32"></div><div class="field"><label for="password">密码</label><input id="password" name="password" type="password" placeholder="请输入密码" autocomplete="current-password" required maxlength="72"></div><button class="btn primary" type="submit">登录 ${icon('arrow')}</button><div class="demo-accounts"><p>演示账号 · 点击填入后登录</p><div class="demo-options"><button type="button" data-action="demo-student">学员账号<small>student / Drive2026!</small></button><button type="button" data-action="demo-admin">管理员账号<small>admin / Admin2026!</small></button></div></div><div class="login-caption">启程驾校 · 学员端 / 管理端</div></form></section></main>`;}
function render(){
  profileDirty=false;
  if(!state)return login();const pages=state.user.role==='admin'?adminPages:studentPages;
  route=location.hash.replace(/^#\//,'').split('?')[0];if(!pages.some(p=>p[0]===route)){route=pages[0][0];history.replaceState(null,'','#/'+route);}
  const current=pages.find(p=>p[0]===route),pending=state.exams.filter(e=>e.status==='pending').length;
  document.title=`${current[1]} · 启程驾校`;
  app.innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#/${pages[0][0]}"><span class="brand-symbol">启</span><span>启程驾校<small>QICHENG DRIVING</small></span></a><div class="nav-label">${state.user.role==='admin'?'教学工作台':'我的学车旅程'}</div><nav class="nav" aria-label="主导航">${pages.map(([r,t,i])=>`<a href="#/${r}" class="${route===r?'active':''}" ${route===r?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${r==='exams'&&pending?`<span class="count">${pending}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-account"><span class="avatar">${esc(state.user.name.slice(-2))}</span><a href="#/profile" class="spacer"><strong>${esc(state.user.name)}</strong><small>${state.user.role==='admin'?'教学管理员':state.user.license+' 学员'}</small></a><button class="logout" data-action="logout" aria-label="退出登录">${icon('logout')}</button></div></div></aside><button class="scrim" data-action="menu" aria-label="关闭菜单"></button><div class="main"><header class="topbar"><div class="breadcrumbs"><button class="mobile-toggle" data-action="menu" aria-label="打开菜单">${icon('menu')}</button><span>${state.user.role==='admin'?'教学管理':'学员中心'}</span><span>/</span><strong>${current[1]}</strong></div><div class="topbar-right"><span class="muted">${dateLabel(state.today)} ${weekLabel(state.today)}</span><span class="role-pill">${state.user.role==='admin'?'管理端':'学员端'}</span><button class="theme-toggle" data-action="theme" aria-label="切换明暗主题">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button><button class="inline-btn" data-action="refresh" aria-label="刷新数据">${icon('clock')}</button></div></header><main class="content">${renderPage()}<footer class="page-footer"><span>启程驾校 · ${state.user.role==='admin'?'让每一次教学安排都有据可循':'每一程，都有进步'}</span><span>学员学习进度与预约管理</span></footer></main></div></div>`;
  enhanceSurfaces();
}
function filterbar({search,subjectFilter=false,statuses,dateFilter=false,license=false,coachFilter=false}={}){const v=f();return `<form class="filterbar" id="filters">${search?`<div class="searchbox">${icon('search')}<input name="q" placeholder="${esc(search)}" value="${esc(v.q||'')}" aria-label="搜索"></div>`:''}${subjectFilter?`<select name="subject" aria-label="筛选科目">${options(subjectOptions(),v.subject,'全部科目')}</select>`:''}${statuses?`<select name="status" aria-label="筛选状态">${options(statuses.map(s=>[s,labels[s][0]]),v.status,'全部状态')}</select>`:''}${dateFilter?`<input name="date" type="date" value="${esc(v.date||'')}" aria-label="筛选日期">`:''}${license?`<select name="license" aria-label="筛选车型">${options([['C1','C1 手动挡'],['C2','C2 自动挡']],v.license,'全部车型')}</select>`:''}${coachFilter?`<select name="coach" aria-label="筛选教练">${options(coachOptions(),v.coach,'全部教练')}</select>`:''}<button class="btn" type="submit">筛选</button>${Object.values(v).some(Boolean)?btn('重置','reset-filters','','ghost'):''}</form>`;}
function renderPage(){switch(route){
  case 'overview':return overview();case 'progress':return progressPage();case 'training':return trainingPage();case 'my-bookings':return bookingsPage(true);case 'my-exams':return myExams();case 'dashboard':return dashboard();case 'students':return studentsPage();case 'hours':return hoursPage();case 'coaches':return coachesPage();case 'vehicles':return vehiclesPage();case 'schedules':return schedulesPage();case 'bookings':return bookingsPage();case 'exams':return examsPage();case 'settings':return settingsPage();case 'logs':return logsPage();case 'profile':return profilePage();default:return '';}}

function roadmap(uid){const current=stage(uid);return `<div class="roadmap">${state.subjects.map(s=>`<div class="roadmap-item ${hasPassed(uid,s.id)?'done':current?.id===s.id?'current':''}"><span class="roadmap-circle">${hasPassed(uid,s.id)?'✓':String(s.id).padStart(2,'0')}</span><strong>${s.name}</strong><span>${hasPassed(uid,s.id)?'已通过':current?.id===s.id?'进行中':'待完成'}</span></div>`).join('')}</div>`;}
function subjectRows(uid){return `<div class="subject-list">${state.subjects.map(s=>{const value=hours(uid,s.id),done=hasPassed(uid,s.id),current=stage(uid)?.id===s.id;return `<div class="subject-row ${current?'current':''}"><div class="subject-number ${done?'done':''}">${done?'✓':String(s.id).padStart(2,'0')}</div><div><div class="between"><h3>${s.name}<small> · ${s.subtitle}</small></h3>${done?badge('passed'):value>=s.required_minutes?badge('good','学时达标'):badge('pending',value?'学习中':'待学习')}</div>${progressBar(value,s.required_minutes)}<div class="between"><small>有效学时 ${hourText(value)} / ${hourText(s.required_minutes)} 小时</small><small>${pct(value,s.required_minutes)}%</small></div></div></div>`;}).join('')}</div>`;}
function upcomingBookings(){return state.bookings.filter(b=>b.status==='booked'&&schedule(b.schedule_id)?.date+' '+schedule(b.schedule_id)?.end_time>state.server_time).sort((a,b)=>(schedule(a.schedule_id).date+schedule(a.schedule_id).start_time).localeCompare(schedule(b.schedule_id).date+schedule(b.schedule_id).start_time));}
function bookingSnippet(b){const s=schedule(b.schedule_id);return `<div class="appointment"><div class="between"><div class="appointment-date">${dateLabel(s.date)} · ${weekLabel(s.date)}</div>${badge(b.status)}</div><div class="appointment-time">${s.start_time} - ${s.end_time}</div><p>${subject(s.subject_id).name}训练 · ${esc(coach(s.coach_id).name)} · ${esc(vehicle(s.vehicle_id).plate)}</p><div class="appointment-footer">${icon('pin')}${esc(s.location)}</div></div>`;}
function overview(){const uid=state.user.id,total=state.subjects.reduce((n,s)=>n+s.required_minutes,0),done=state.subjects.reduce((n,s)=>n+Math.min(hours(uid,s.id),s.required_minutes),0),next=upcomingBookings()[0],c=coach(state.user.coach_id),current=stage(uid);return heading(`${greeting()}，${esc(state.user.name)}`,'把每一次练习，变成向前的一小步。',nav('training',`${icon('plus')} 预约练车`,'primary'),'MY LEARNING JOURNEY')+`<div class="training-banner"><div><div class="eyebrow">${current?'当前学习阶段':'学习生涯已完成'}</div><h2>${current?current.name+' · '+current.subtitle:'四项科目已全部通过'}</h2><p>${current?`已完成 ${hourText(hours(uid,current.id))} 小时，${hours(uid,current.id)>=current.required_minutes?'学时已达标，可以查看考试登记条件。':`距离学时目标还差 ${hourText(current.required_minutes-hours(uid,current.id))} 小时。`}`:'每一份付出都有回响，祝你一路平安。'}</p></div>${nav('progress','查看进度 '+icon('arrow'))}</div><div class="two-col"><section class="paper"><div class="paper-head"><h2>我的学习进度</h2><a href="#/progress" class="link small">学时明细 →</a></div><div class="progress-summary"><div class="progress-ring" style="--progress:${pct(done,total)}%"><div class="ring-center"><strong>${pct(done,total)}<span class="small">%</span></strong><small>学时完成度</small></div></div><div><h2>${state.subjects.filter(s=>hasPassed(uid,s.id)).length} / 4 个科目已通过</h2><p>已计入 ${hourText(hours(uid))} 小时学习与训练<br>报考车型 ${esc(state.user.license)} · 学时由管理员登记</p></div></div>${subjectRows(uid)}</section><div class="stack">${paper('下一次训练',next?bookingSnippet(next):empty('还没有待参加的训练','提前安排，让练习更有节奏。',nav('training','查看可约时段','primary')),`<a href="#/my-bookings" class="link small">全部预约 →</a>`)}${paper('我的教练',`<div class="paper-body"><div class="coach-profile"><span class="avatar">${esc(c.name.slice(-2))}</span><div><h3>${esc(c.name)}</h3><p>${c.experience?c.experience+' 年教龄 · ':''}${esc(c.phone)}</p></div></div><p class="coach-quote">${esc(c.description||'如需调整教练，请联系教学管理员。')}</p></div>`)}<div class="note-line">${icon('info')}<span>外部预约成功后，请登记考试通知，方便教练安排考前练习。</span></div></div></div>`;}
function hourTable(records,admin=false){return table([...(admin?['学员']:[]),'学习科目','学习日期','有效时长','学习内容','状态','录入人',...(admin?['操作']:[])],records.map(h=>[...(admin?[person(user(h.student_id))]:[]),subject(h.subject_id).name,esc(h.date),`<strong>${hourText(h.minutes)}</strong> 小时`,`<div class="cell-note">${esc(h.note)}${h.status==='void'?`<div class="cell-sub">作废原因：${esc(h.void_reason)}</div>`:''}</div>`,badge(h.status),esc(h.operator_name),...(admin?[h.status==='valid'?action('作废','void-hour',h.id,'danger'):'-']:[])]));}
function progressPage(){const uid=state.user.id,v=f();return heading('学习进度','从科目一到科目四，记录你的每一步成长。',btn(icon('download')+' 导出学时','export-hours'))+roadmap(uid)+`<div class="equal-col mb">${state.subjects.map(s=>`<section class="paper"><div class="paper-body"><div class="between"><h2>${s.name}</h2>${hasPassed(uid,s.id)?badge('passed'):hours(uid,s.id)>=s.required_minutes?badge('active','学时达标'):badge('pending','待完成')}</div><p class="muted small">${s.subtitle}</p><div class="between mt"><span><strong class="metric" style="font-size:24px">${hourText(hours(uid,s.id))}</strong><span class="muted small"> / ${hourText(s.required_minutes)} 小时</span></span><span class="muted small">${pct(hours(uid,s.id),s.required_minutes)}%</span></div>${progressBar(hours(uid,s.id),s.required_minutes)}</div></section>`).join('')}</div><div class="section-title"><h2>学时记录</h2><span>作废记录不计入有效学时</span></div>${filterbar({subjectFilter:true,statuses:['valid','void']})}${hourTable(state.hours.filter(h=>(!v.subject||h.subject_id===+v.subject)&&(!v.status||h.status===v.status)))}`;}
function trainingPage(){const v=f();if(!v.date)v.date=state.today;const canTrain=hasPassed(state.user.id,1);const list=state.schedules.filter(s=>s.date===v.date&&s.status==='open'&&vehicle(s.vehicle_id).license===state.user.license&&coach(s.coach_id).status==='active'&&vehicle(s.vehicle_id).status==='active'&&(!v.subject||s.subject_id===+v.subject)&&(!v.coach||s.coach_id===+v.coach));return heading('练车预约','选择训练时段，教练和教学车辆将一并确定。',nav('my-bookings','我的训练 '+icon('arrow')))+(!canTrain?'<div class="alert">通过科目一后，即可预约科目二、科目三驾驶训练。</div>':'')+`<div class="date-strip">${Array.from({length:7},(_,i)=>{const d=addDay(i);return `<button class="date-button ${v.date===d?'active':''}" data-action="pick-date" data-id="${d}" aria-pressed="${v.date===d}"><span>${i===0?'今天':weekLabel(d)}</span><strong>${d.slice(8)}</strong><span>${Number(d.slice(5,7))}月</span></button>`;}).join('')}</div>${filterbar({subjectFilter:true,coachFilter:true,dateFilter:true})}<div class="section-title"><h2>${dateLabel(v.date)}的训练</h2><span>${list.length} 个场次 · ${esc(state.user.license)} 车型</span></div><div class="schedule-list">${list.length?list.map(s=>{const mine=state.bookings.some(b=>b.schedule_id===s.id&&b.status!=='cancelled'),full=s.booked_count>=s.capacity,expired=s.date+' '+s.start_time<=state.server_time,disabled=mine||full||expired||!canTrain;return `<article class="schedule-card ${full&&!mine?'full':''}"><div class="time-block"><div class="time">${s.start_time}-${s.end_time}</div><div class="meta">${subject(s.subject_id).name} · ${esc(vehicle(s.vehicle_id).license)} ${vehicle(s.vehicle_id).license==='C1'?'手动挡':'自动挡'}</div></div><div><h3>${esc(coach(s.coach_id).name)}<span class="muted small"> · ${coach(s.coach_id).experience} 年教龄</span></h3><div class="details"><span>${esc(vehicle(s.vehicle_id).plate)}</span><span>${esc(s.location)}</span></div></div><div class="side"><p>剩余 ${Math.max(0,s.capacity-s.booked_count)} / ${s.capacity} 个名额</p>${btn(mine?'已预约':expired?'已开始':full?'已约满':'预约训练','book-training',s.id,'primary',disabled?'disabled':'')}</div></article>`;}).join(''):`<div class="paper">${empty('当天没有符合条件的场次','试试其他日期，或调整科目和教练筛选。')}</div>`}</div>`;}
function bookingsPage(mine=false){const v=f(),list=state.bookings.filter(b=>{const s=schedule(b.schedule_id);return (!v.q||matches(user(b.student_id).name+vehicle(s.vehicle_id).plate,v.q))&&(!v.status||b.status===v.status)&&(!v.date||s.date===v.date)&&(!v.subject||s.subject_id===+v.subject);});return heading(mine?'我的训练':'练车预约管理',mine?'查看训练安排、历史记录和有效训练时长。':'查看学员预约，训练结束后登记结果并计入有效学时。',mine?nav('training',icon('plus')+' 预约练车','primary'):'')+filterbar({search:mine?undefined:'搜索学员姓名 / 车牌',subjectFilter:true,statuses:['booked','completed','cancelled','absent'],dateFilter:true})+table([...(mine?[]:['学员']),'日期与时间','科目 / 车辆','教练 / 地点','状态','操作'],list.map(b=>{const s=schedule(b.schedule_id),future=s.date+' '+s.start_time>state.server_time,ended=s.date+' '+s.end_time<=state.server_time,h=state.hours.find(h=>h.booking_id===b.id);return [...(mine?[]:[person(user(b.student_id))]),`<div class="cell-title">${s.date}</div><div class="cell-sub">${s.start_time}-${s.end_time}</div>`,`<div>${subject(s.subject_id).name} · ${esc(vehicle(s.vehicle_id).license)}</div><div class="cell-sub">${esc(vehicle(s.vehicle_id).plate)}</div>`,`<div>${esc(coach(s.coach_id).name)}</div><div class="cell-sub">${esc(s.location)}</div>`,`<div>${badge(b.status)}</div>${h?`<div class="cell-sub">${h.status==='valid'?'计入':'已作废'} ${hourText(h.minutes)} 小时</div>`:''}`,`<div class="actions">${b.status==='booked'&&future?action('取消预约','cancel-booking',b.id,'danger'):''}${!mine&&b.status==='booked'&&ended?action('登记完成','complete-booking',b.id)+action('未到场','absent-booking',b.id,'danger'):''}${b.status!=='booked'||(!future&&(mine||!ended))?'-':''}</div>`];}));}
function examRows(list,admin=false){return table([...(admin?['学员']:[]),'考试科目','交管考试时间 / 考场','预约凭证','核对状态','外部成绩','操作'],list.map(e=>[...(admin?[person(user(e.student_id))]:[]),subject(e.subject_id).name,`<div class="cell-title">${e.exam_date||'待补充'} ${esc(e.exam_time)}</div><div class="cell-sub">${esc(e.location||'待补充考场')}</div>`,`<div class="cell-note">${esc(e.booking_reference||'历史记录')}${e.note?'<div class="cell-sub">'+esc(e.note)+'</div>':''}</div>`,badge(e.status,e.status==='cancelled'?'已撤回':undefined),e.score!==null?`<strong>${e.score}</strong> 分<div class="cell-sub">${esc(e.result_source||'历史导入')}</div>`:'待同步',`<div class="actions">${admin?(e.status==='pending'?action('确认信息','verify-exam',e.id)+action('退回补充','return-exam',e.id,'danger'):e.status==='approved'?action('同步成绩','result-exam',e.id)+action('退回更正','return-exam',e.id,'danger'):'-'):(['pending','approved'].includes(e.status)?action('撤回登记','cancel-exam',e.id,'danger'):'-')}</div>`]));}
function myExams(){const uid=state.user.id,v=f();return heading('考试信息','填报交管考场的预约通知，让教练为你安排考前训练。')+`<div class="note-line mb">${icon('info')}<span>学时达标后，请自行在交管渠道完成预约，再登记通知中的时间、考场和凭证。驾校只核对信息与安排练习。</span></div><div class="cards-grid mb">${state.subjects.map(s=>{const reasons=state.eligibility[s.id],passed=hasPassed(uid,s.id),pending=state.exams.find(e=>e.subject_id===s.id&&['pending','approved'].includes(e.status));return `<article class="exam-card"><div class="between"><h2>${s.name}</h2>${passed?badge('passed'):pending?badge(pending.status):''}</div><p class="subtitle">${s.subtitle}</p><div class="exam-hours"><span>有效学时</span><span>${hourText(hours(uid,s.id))} / ${hourText(s.required_minutes)} 小时</span></div>${progressBar(hours(uid,s.id),s.required_minutes)}<p class="reason ${!reasons.length?'ready':''}">${passed?'外部考试通过结果已归档。':pending?esc(pending.exam_date+' '+pending.exam_time+' / '+pending.location):reasons.length?esc(reasons.join('；')):'学时已达标，外部预约成功后可登记考试信息。'}</p>${btn(passed?'本科目已通过':pending?'已登记考试信息':'登记考试信息','apply-exam',s.id,'primary',reasons.length?'disabled':'')}</article>`;}).join('')}</div><div class="section-title"><h2>考试登记记录</h2><span>核对记录与外部考试结果</span></div>${filterbar({subjectFilter:true,statuses:['pending','approved','passed','failed','rejected','cancelled']})}${examRows(state.exams.filter(e=>(!v.subject||e.subject_id===+v.subject)&&(!v.status||e.status===v.status)))}`;}

function dashboard(){
  const active=state.students.filter(s=>s.status==='active'),todaySchedules=state.schedules.filter(s=>s.date===state.today&&s.status==='open'),pending=state.exams.filter(e=>e.status==='pending'),awaiting=state.bookings.filter(b=>b.status==='booked'&&schedule(b.schedule_id).date+' '+schedule(b.schedule_id).end_time<=state.server_time),soon=state.exams.filter(e=>e.status==='approved'&&e.exam_date>=state.today&&e.exam_date<=addDay(7)).sort((a,b)=>(a.exam_date+a.exam_time).localeCompare(b.exam_date+b.exam_time));
  return heading('教学概览','掌握训练安排，跟进近期考试。',btn(icon('plus')+' 发布训练','new-schedule','','primary'))+
  `<section class="overview-metrics"><div class="stat"><div class="stat-title">在学学员</div><div class="stat-value">${active.length}<small>位</small></div><div class="stat-foot">已分配教练 ${active.filter(s=>s.coach_id).length} 位</div></div><div class="stat"><div class="stat-title">今日训练</div><div class="stat-value">${todaySchedules.length}<small>场</small></div><div class="stat-foot">${state.bookings.filter(b=>b.status!=='cancelled'&&schedule(b.schedule_id).date===state.today).length} 人次预约</div></div><div class="stat featured"><div class="stat-title">未来七天考试</div><div class="stat-value">${soon.length}<small>人次</small></div><div class="stat-foot">已核对交管考试信息</div></div><div class="stat"><div class="stat-title">可用教学车辆</div><div class="stat-value">${state.vehicles.filter(v=>v.status==='active').length}<small>辆</small></div><div class="stat-foot">维修中 ${state.vehicles.filter(v=>v.status==='maintenance').length} 辆</div></div></section>
  <div class="two-col dashboard-grid"><div class="stack">${paper('今日训练安排',todaySchedules.length?`<div class="table-scroll"><table><thead><tr><th>训练时段</th><th>教练 / 科目</th><th>教学车辆</th><th>预约</th></tr></thead><tbody>${todaySchedules.map(s=>`<tr><td><strong>${s.start_time}</strong><div class="cell-sub">至 ${s.end_time}</div></td><td>${esc(coach(s.coach_id).name)}<div class="cell-sub">${subject(s.subject_id).name} / ${esc(s.location)}</div></td><td>${esc(vehicle(s.vehicle_id).plate)}<div class="cell-sub">${esc(vehicle(s.vehicle_id).license)}</div></td><td>${s.booked_count} / ${s.capacity}<div class="cell-sub">${s.date+' '+s.end_time<state.server_time?'已结束':s.date+' '+s.start_time<state.server_time?'进行中':'待开始'}</div></td></tr>`).join('')}</tbody></table></div>`:empty('今天没有训练排班','发布场次后，学员即可查看和预约。'),'<a href="#/schedules" class="link small">查看全部 '+icon('arrow')+'</a>')}
  ${paper('学员学习阶段',`<div class="stage-distribution">${state.subjects.map(s=>{const n=active.filter(u=>stage(u.id)?.id===s.id).length;return `<div class="stage-stat"><span>${s.name}</span><strong>${n}<small>位</small></strong>${progressBar(n,Math.max(active.length,1))}</div>`;}).join('')}</div>`)}</div>
  <div class="stack">${paper('近期考试 / 考前训练',soon.length?soon.map(e=>{const upcoming=state.bookings.filter(b=>b.student_id===e.student_id&&b.status==='booked'&&schedule(b.schedule_id).subject_id===e.subject_id&&schedule(b.schedule_id).date>=state.today&&schedule(b.schedule_id).date<e.exam_date);return `<div class="exam-agenda"><div class="exam-date"><strong>${e.exam_date.slice(8)}</strong><span>${Number(e.exam_date.slice(5,7))}月</span></div><div class="spacer"><h3>${esc(user(e.student_id).name)}<span class="muted small"> / ${subject(e.subject_id).name}</span></h3><p>${esc(e.exam_time)} / ${esc(e.location)}</p><p>考前已约 ${upcoming.length} 场练习</p>${[2,3].includes(e.subject_id)&&e.exam_date>addDay(1)?action('发布考前场次','prep-training',e.id):''}</div></div>`;}).join(''):empty('暂无近期考试','学员登记并核对考试通知后，会显示在这里。'),'<a href="#/exams" class="link small">考试信息 '+icon('arrow')+'</a>')}
  ${paper('需要跟进',`<div class="task-list"><a class="task" href="#/exams"><span class="task-num">${pending.length}</span><div class="spacer"><h3>考试信息待核对</h3><p>核对学员填报的时间、考场和预约凭证</p></div>${icon('arrow')}</a><a class="task" href="#/bookings"><span class="task-num">${awaiting.length}</span><div class="spacer"><h3>训练结果待登记</h3><p>确认到场情况与实际训练时长</p></div>${icon('arrow')}</a></div>`)}
  ${paper('最近操作',state.logs.slice(0,3).map(l=>`<div class="log-row"><span class="log-mark">${icon('file')}</span><div><strong>${esc(l.action)}</strong><p>${esc(logText(l.detail))}</p><p>${esc(l.operator_name)} / ${l.created_at.slice(5,16)}</p></div></div>`).join(''),'<a href="#/logs" class="link small">全部记录 '+icon('arrow')+'</a>')}</div></div>`;
}
function studentsPage(){const v=f(),list=state.students.filter(s=>matches(s.name+s.username+s.phone,v.q)&&(!v.status||s.status===v.status)&&(!v.license||s.license===v.license));return heading('学员管理','管理学员档案，分配教练，跟进学习阶段。',btn(icon('plus')+' 新增学员','new-student','','primary'))+filterbar({search:'搜索姓名 / 账号 / 手机',statuses:['active','inactive'],license:true})+table(['学员','联系方式','报考车型','当前阶段','学时进度','负责教练','账号状态','操作'],list.map(s=>{const current=stage(s.id),total=state.subjects.reduce((n,x)=>n+x.required_minutes,0),completed=state.subjects.reduce((n,x)=>n+Math.min(hours(s.id,x.id),x.required_minutes),0);return [person(s),esc(s.phone),esc(s.license),current?.name||'已结业',`<div class="mini-progress"><span>${hourText(hours(s.id))} 小时</span>${progressBar(completed,total)}</div>`,esc(coach(s.coach_id).name),badge(s.status),`<div class="actions">${action('详情','student-detail',s.id)}${action('编辑','edit-student',s.id)}</div>`];}));}
function hoursPage(){const v=f(),list=state.hours.filter(h=>matches(user(h.student_id).name+h.note,v.q)&&(!v.subject||h.subject_id===+v.subject)&&(!v.status||h.status===v.status)&&(!v.date||h.date===v.date));return heading('学时管理','由管理员录入有效学习时长，所有调整保留操作记录。',`<div class="row">${btn(icon('download')+' 导出','export-hours')}${btn(icon('plus')+' 录入学时','new-hour','','primary')}</div>`)+filterbar({search:'搜索学员 / 学习内容',subjectFilter:true,statuses:['valid','void'],dateFilter:true})+hourTable(list,true);}
function coachesPage(){const v=f(),list=state.coaches.filter(c=>matches(c.name+c.phone,v.q)&&(!v.status||c.status===v.status));return heading('教练管理','维护教练信息与教学车型，合理分配教学资源。',btn(icon('plus')+' 新增教练','new-coach','','primary'))+filterbar({search:'搜索教练 / 手机',statuses:['active','inactive']})+`<div class="resource-grid">${list.length?list.map(c=>`<article class="resource-card"><div class="between"><div class="row"><span class="avatar">${esc(c.name.slice(-2))}</span><div><h2>${esc(c.name)}</h2><p class="muted small">${esc(c.phone)}</p></div></div>${badge(c.status)}</div><p class="description">${esc(c.description||'暂无教学介绍')}</p><div class="resource-details"><div><small>教学车型</small><strong>${esc(c.license)}</strong></div><div><small>教龄</small><strong>${c.experience} 年</strong></div><div><small>负责学员</small><strong>${state.students.filter(s=>s.coach_id===c.id&&s.status==='active').length} 位</strong></div></div>${btn('编辑教练','edit-coach',c.id,'slim')}</article>`).join(''):empty('没有符合条件的教练','调整搜索条件或新增教练。')}</div>`;}
function vehiclesPage(){const v=f(),list=state.vehicles.filter(c=>matches(c.plate+c.model,v.q)&&(!v.status||c.status===v.status)&&(!v.license||c.license===v.license));return heading('车辆管理','维护教学车辆与使用状态，让每一次安排都有保障。',btn(icon('plus')+' 新增车辆','new-vehicle','','primary'))+filterbar({search:'搜索车牌 / 品牌型号',statuses:['active','maintenance','inactive'],license:true})+`<div class="resource-grid">${list.length?list.map(c=>`<article class="resource-card"><div class="vehicle-glyph" aria-hidden="true">${icon('car')}</div><div class="between"><div class="vehicle-plate">${esc(c.plate)}</div>${badge(c.status)}</div><p class="muted small">${esc(c.model)}</p><div class="resource-details"><div><small>教学车型</small><strong>${esc(c.license)} ${c.license==='C1'?'手动挡':'自动挡'}</strong></div><div><small>未来场次</small><strong>${state.schedules.filter(s=>s.vehicle_id===c.id&&s.status==='open'&&s.date+' '+s.end_time>state.server_time).length} 场</strong></div></div>${btn('编辑车辆','edit-vehicle',c.id,'slim')}</article>`).join(''):empty('没有符合条件的车辆','调整搜索条件或新增教学车辆。')}</div>`;}
function schedulesPage(){const v=f(),list=state.schedules.filter(s=>(!v.date||s.date===v.date)&&(!v.subject||s.subject_id===+v.subject)&&(!v.status||s.status===v.status)&&(!v.coach||s.coach_id===+v.coach));return heading('训练排班','统一安排时间、教练与车辆，发布后学员即可预约。',btn(icon('plus')+' 发布训练','new-schedule','','primary'))+filterbar({subjectFilter:true,dateFilter:true,coachFilter:true,statuses:['open','cancelled']})+table(['训练日期 / 时间','科目','教练','教学车辆','地点','预约人数','状态','操作'],list.map(s=>[`<div class="cell-title">${s.date} <span class="muted small">${weekLabel(s.date)}</span></div><div class="cell-sub">${s.start_time}-${s.end_time}</div>`,subject(s.subject_id).name,esc(coach(s.coach_id).name),`<div>${esc(vehicle(s.vehicle_id).plate)}</div><div class="cell-sub">${esc(vehicle(s.vehicle_id).license)} · ${esc(vehicle(s.vehicle_id).model)}</div>`,esc(s.location),`${s.booked_count} / ${s.capacity}`,s.status==='cancelled'?badge('cancelled'):s.date+' '+s.end_time<state.server_time?badge('completed','已结束'):s.date+' '+s.start_time<state.server_time?badge('booked','进行中'):badge('open'),s.status==='open'&&s.date+' '+s.start_time>state.server_time?action('取消场次','cancel-schedule',s.id,'danger'):'-']));}
function examsPage(){const v=f(),list=state.exams.filter(e=>matches(user(e.student_id).name+e.location,v.q)&&(!v.subject||e.subject_id===+v.subject)&&(!v.status||e.status===v.status));return heading('考试信息核对','核对学员填报的交管考场通知，为考前训练提供依据。')+`<div class="note-line mb">${icon('info')}<span>驾校核对外部预约通知，并据此安排考前练习。考试时间、地点以交管通知为准。</span></div>`+filterbar({search:'搜索学员 / 考场',subjectFilter:true,statuses:['pending','approved','passed','failed','rejected','cancelled']})+examRows(list,true);}
function settingsPage(){return heading('科目规则','设置各科目的学习时长门槛与成绩通过线。')+`<div class="note-line mb">${icon('info')}<span>这里的数值用于本驾校系统的教学流程配置。更改学时门槛前，请先核对正在处理的考试登记。</span></div><section class="paper">${state.subjects.map(s=>`<div class="settings-rule"><div><h2>${s.name}</h2><p>${s.subtitle}</p></div><div><span class="muted small">要求学时</span><div><strong>${hourText(s.required_minutes)}</strong> 小时</div></div><div><span class="muted small">成绩通过线</span><div><strong>${s.pass_score}</strong> 分</div></div>${btn('修改规则','edit-subject',s.id)}</div>`).join('')}</section>`;}
function logsPage(){const v=f();return heading('操作记录','记录账号、教学资源、学时和预约的关键变更。')+filterbar({search:'搜索操作 / 内容 / 操作人'})+table(['操作时间','操作人','操作类型','具体内容'],state.logs.filter(l=>matches(l.action+l.detail+l.operator_name,v.q)).map(l=>[esc(l.created_at),esc(l.operator_name),esc(l.action),`<div class="cell-note">${esc(logText(l.detail))}</div>`]));}
function profilePage(){const u=state.user;return heading('个人资料','维护联系信息与账号密码。')+`<section class="paper profile-page"><div class="profile-banner"><span class="avatar">${esc(u.name.slice(-2))}</span><div><h2>${esc(u.name)}</h2><p>${esc(u.username)} · ${u.role==='admin'?'教学管理员':u.license+' 学员'}</p></div></div><form class="paper-body" id="profile-form"><div class="form-error" role="alert"></div><div class="form-grid">${field({name:'name',label:'姓名',value:u.name,maxlength:30})}${field({name:'phone',label:'手机号码',value:u.phone,type:'tel',pattern:'1[0-9]{10}',maxlength:11})}<div class="field full"><label>账号</label><input value="${esc(u.username)}" disabled><small>账号由管理员建立，不能自行修改。</small></div><div class="field full"><h3 class="mt">修改密码</h3><small>不修改密码时，请将以下两项留空。</small></div>${field({name:'old_password',label:'原密码',type:'password',required:false,autocomplete:'current-password'})}${field({name:'new_password',label:'新密码',type:'password',required:false,minlength:8,maxlength:72,autocomplete:'new-password'})}</div><div class="form-footer"><button class="btn primary" type="submit">保存资料</button></div></form></section>`;}

function field(o){const {name,label,type='text',value='',required=true,opts,help,full=false,...attrs}=o;const attr=Object.entries(attrs).map(([k,v])=>`${k}="${esc(v)}"`).join(' ');return `<div class="field ${full?'full':''}"><label for="field-${name}">${esc(label)}${required?'<span class="required">*</span>':''}</label>${type==='select'?`<select id="field-${name}" name="${name}" ${required?'required':''} ${attr}>${options(opts,value,required?'请选择':undefined)}</select>`:type==='textarea'?`<textarea id="field-${name}" name="${name}" ${required?'required':''} ${attr}>${esc(value)}</textarea>`:`<input id="field-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${attr}>`}${help?`<small>${esc(help)}</small>`:''}</div>`;}
let modalSubmit=null,returnFocus=null;
function showForm(title,fields,onSubmit,{description='',submit='保存',danger=false}={}){returnFocus=document.activeElement;modalSubmit=onSubmit;modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="close-modal" data-action="close-modal" aria-label="关闭弹窗">${icon('close')}</button></div><form id="modal-form" class="modal-body">${description?`<p class="modal-description">${esc(description)}</p>`:''}<div class="form-error" role="alert"></div><div class="form-grid">${fields.map(field).join('')}</div><div class="form-footer"><button type="button" class="btn" data-action="close-modal">取消</button><button type="submit" class="btn ${danger?'danger':'primary'}">${esc(submit)}</button></div></form>`;modal.showModal();}
function closeModal(){modal.close();modalSubmit=null;if(returnFocus?.isConnected)returnFocus.focus();}
function confirmAction(title,description,onSubmit,danger=false){showForm(title,[],onSubmit,{description,submit:'确认'+(danger?'操作':''),danger});}
function showDetails(title,html){returnFocus=document.activeElement;modalSubmit=null;modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="close-modal" data-action="close-modal" aria-label="关闭弹窗">${icon('close')}</button></div><div class="modal-body">${html}</div>`;modal.showModal();}
async function mutate(path,method,body,message){await api(path,{method,body});closeModal();await refresh();toast(message);}
function studentForm(id){const s=id?user(+id):null;showForm(s?'编辑学员':'新增学员',[
  ...(!s?[{name:'username',label:'登录账号',minlength:3,maxlength:32,pattern:'[a-zA-Z0-9_]{3,32}',help:'3～32 位字母、数字或下划线'}]:[]),
  {name:'name',label:'学员姓名',value:s?.name,maxlength:30},{name:'phone',label:'手机号码',type:'tel',value:s?.phone,pattern:'1[0-9]{10}',maxlength:11},
  ...(!s?[{name:'license',label:'报考车型',type:'select',opts:[['C1','C1 手动挡'],['C2','C2 自动挡']],value:'C1'}]:[]),
  {name:'coach_id',label:'负责教练',type:'select',opts:[[0,'暂不分配'],...coachOptions(s?.license)],value:s?.coach_id||0},
  ...(s?[{name:'status',label:'账号状态',type:'select',opts:[['active','正常'],['inactive','停用']],value:s.status}]:[]),
  {name:'password',label:s?'重置密码（留空则保持）':'初始密码',type:'password',required:!s,minlength:8,maxlength:72,autocomplete:'new-password',full:true,help:s?'停用账号会同时取消该学员尚未完成的练车和考试登记。':'密码至少 8 位，创建后请告知学员。'}
],v=>mutate(s?'students/'+s.id:'students',s?'PATCH':'POST',{...v,coach_id:Number(v.coach_id)},s?'学员信息已更新':'学员已创建'));}
function resourceForm(type,id){const isCoach=type==='coaches',item=id?(isCoach?coach(+id):vehicle(+id)):null;showForm((item?'编辑':'新增')+(isCoach?'教练':'车辆'),[
  ...(isCoach?[{name:'name',label:'教练姓名',value:item?.name,maxlength:30},{name:'phone',label:'手机号码',type:'tel',value:item?.phone,pattern:'1[0-9]{10}',maxlength:11}]:[{name:'plate',label:'车牌号码',value:item?.plate,maxlength:16},{name:'model',label:'品牌型号',value:item?.model,maxlength:40}]),
  {name:'license',label:isCoach?'教学车型':'车辆车型',type:'select',opts:isCoach?[['C1','C1'],['C2','C2'],['C1/C2','C1 / C2']]:[['C1','C1 手动挡'],['C2','C2 自动挡']],value:item?.license||'C1'},
  ...(isCoach?[{name:'experience',label:'教龄（年）',type:'number',value:item?.experience??1,min:0,max:60,step:1}]:[]),
  {name:'status',label:'使用状态',type:'select',opts:(isCoach?['active','inactive']:['active','maintenance','inactive']).map(s=>[s,labels[s][0]]),value:item?.status||'active'},
  ...(isCoach?[{name:'description',label:'教学介绍',type:'textarea',value:item?.description,required:false,maxlength:240,full:true}]:[])
],v=>mutate(type+(item?'/'+item.id:''),item?'PATCH':'POST',{...v,...(isCoach?{experience:+v.experience}:{})},'信息已保存'),{description:item?'有未结束排班时，需要先取消相关场次，才能停用资源或更改车型。':''});}
function scheduleForm(pref={}){showForm('发布训练场次',[
  {name:'subject_id',label:'训练科目',type:'select',opts:[[2,'科目二 · 场地驾驶'],[3,'科目三 · 道路驾驶']],value:pref.subject_id||2},
  {name:'date',label:'训练日期',type:'date',value:pref.date||addDay(1),min:state.today,max:pref.exam_date?addDay(-1,pref.exam_date):''},
  {name:'start_time',label:'开始时间',type:'time',value:'08:00'},{name:'end_time',label:'结束时间',type:'time',value:'10:00'},
  {name:'coach_id',label:'教练',type:'select',opts:coachOptions(),value:pref.coach_id||''},
  {name:'vehicle_id',label:'教学车辆',type:'select',opts:state.vehicles.filter(v=>v.status==='active').map(v=>[v.id,`${v.plate} · ${v.license}`])},
  {name:'capacity',label:'预约名额',type:'number',value:1,min:1,max:8,step:1,help:'同一场次的学员共用该教练与车辆，管理员按实际训练录入学时。'},
  {name:'location',label:'训练地点',value:'启程一号训练场',maxlength:80}
],v=>mutate('schedules','POST',{...v,subject_id:+v.subject_id,coach_id:+v.coach_id,vehicle_id:+v.vehicle_id,capacity:+v.capacity},'训练场次已发布'),{description:'系统会检查教练和车辆的时间冲突，以及教学车型是否匹配。',submit:'发布场次'});}
function hourForm(){showForm('录入有效学时',[
  {name:'student_id',label:'学员',type:'select',opts:studentOptions(),full:true},
  {name:'subject_id',label:'学习科目',type:'select',opts:subjectOptions(),value:1},
  {name:'date',label:'学习日期',type:'date',value:state.today,max:state.today},
  {name:'minutes',label:'有效时长（分钟）',type:'number',min:1,max:1440,step:1,value:60,help:'60 分钟计为 1 小时。'},
  {name:'note',label:'学习内容',type:'textarea',maxlength:200,full:true,placeholder:'例如：科目二倒车入库、侧方停车训练'}
],v=>mutate('hours','POST',{...v,student_id:+v.student_id,subject_id:+v.subject_id,minutes:+v.minutes},'学时已录入，学员进度已更新'),{description:'请核对学员、科目和实际完成时长。录入后会立即计入有效学时。',submit:'确认录入'});}
function studentDetail(id){const s=user(+id);showDetails(s.name+' · 学习档案',`<div class="details-grid"><div><small>账号</small>${esc(s.username)}</div><div><small>联系方式</small>${esc(s.phone)}</div><div><small>报考车型</small>${esc(s.license)}</div><div><small>负责教练</small>${esc(coach(s.coach_id).name)}</div></div>${roadmap(s.id)}${state.subjects.map(x=>`<div class="detail-progress"><div class="between"><strong>${x.name}</strong>${hasPassed(s.id,x.id)?badge('passed'):badge('pending',hours(s.id,x.id)>=x.required_minutes?'学时达标':'学习中')}</div>${progressBar(hours(s.id,x.id),x.required_minutes)}<span class="muted small">有效学时 ${hourText(hours(s.id,x.id))} / ${hourText(x.required_minutes)} 小时</span></div>`).join('')}`);}
function exportHours(){const v=f(),list=state.hours.filter(h=>(!v.q||matches(user(h.student_id).name+h.note,v.q))&&(!v.subject||h.subject_id===+v.subject)&&(!v.status||h.status===v.status)&&(!v.date||h.date===v.date));const cell=x=>'"'+String(x??'').replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"';const csv='\uFEFF'+[['学员','账号','科目','日期','分钟','小时','状态','内容','录入人','作废原因'],...list.map(h=>[user(h.student_id).name,user(h.student_id).username,subject(h.subject_id).name,h.date,h.minutes,hourText(h.minutes),labels[h.status][0],h.note,h.operator_name,h.void_reason])].map(row=>row.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='学时记录_'+state.today+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('学时记录已导出');}

async function handleAction(name,id,button){switch(name){
  case 'demo-student':$('#username').value='student';$('#password').value='Drive2026!';break;
  case 'demo-admin':$('#username').value='admin';$('#password').value='Admin2026!';break;
  case 'menu':$('.sidebar')?.classList.toggle('open');break;
  case 'close-modal':closeModal();break;
  case 'logout':confirmAction('退出登录','确认退出当前账号？',async()=>{await api('logout',{method:'POST',body:{}});closeModal();login();});break;
  case 'refresh':if(!refreshing){refreshing=true;try{await refresh();toast('数据已更新');}finally{refreshing=false;}}break;
  case 'reset-filters':filters[route]={};render();break;
  case 'pick-date':f().date=id;render();break;
  case 'new-student':studentForm();break;case 'edit-student':studentForm(id);break;case 'student-detail':studentDetail(id);break;
  case 'new-coach':resourceForm('coaches');break;case 'edit-coach':resourceForm('coaches',id);break;
  case 'new-vehicle':resourceForm('vehicles');break;case 'edit-vehicle':resourceForm('vehicles',id);break;
  case 'new-schedule':scheduleForm();break;case 'new-hour':hourForm();break;
  case 'void-hour':showForm('作废学时记录',[{name:'reason',label:'作废原因',type:'textarea',maxlength:120,full:true}],v=>mutate('hours/'+id,'DELETE',v,'记录已作废，有效学时已重新计算'),{description:'作废后保留原始记录，但不再计入有效学时。',submit:'确认作废',danger:true});break;
  case 'cancel-schedule':confirmAction('取消训练场次','该场次的未完成预约也将同步取消，学员可在预约记录中查看。',()=>mutate('schedules/'+id,'PATCH',{status:'cancelled'},'场次及关联预约已取消'),true);break;
  case 'book-training':{const s=schedule(+id);confirmAction('确认预约训练',`${s.date} ${s.start_time}-${s.end_time}，${coach(s.coach_id).name}，${vehicle(s.vehicle_id).plate}，${s.location}。`,()=>mutate('bookings','POST',{schedule_id:+id},'训练预约成功'));break;}
  case 'cancel-booking':confirmAction('取消练车预约','取消后将释放本次预约名额，你可以重新选择其他时段。',()=>mutate('bookings/'+id,'PATCH',{status:'cancelled'},'预约已取消'),true);break;
  case 'complete-booking':{const b=state.bookings.find(x=>x.id===+id),s=schedule(b.schedule_id),duration=(+s.end_time.slice(0,2)*60+ +s.end_time.slice(3))-(+s.start_time.slice(0,2)*60+ +s.start_time.slice(3));showForm('登记训练完成',[{name:'minutes',label:'有效训练时长（分钟）',type:'number',value:duration,min:1,max:duration,step:1,full:true}],v=>mutate('bookings/'+id,'PATCH',{status:'completed',minutes:+v.minutes},'训练已完成，学时已计入'),{description:`${user(b.student_id).name} · ${subject(s.subject_id).name} · ${s.date}。填写该学员实际训练时长，系统将自动生成一条学时记录。`,submit:'完成并计入学时'});break;}
  case 'absent-booking':confirmAction('登记未到场','该学员本次训练将标记为未到场，不计入学时。',()=>mutate('bookings/'+id,'PATCH',{status:'absent'},'已登记未到场'),true);break;
  case 'apply-exam':showForm('登记'+subject(+id).name+'考试信息',[
    {name:'exam_date',label:'外部预约考试日期',type:'date',value:addDay(3),min:state.today},
    {name:'exam_time',label:'通知中的考试时间',type:'time',value:'09:00'},
    {name:'location',label:'交管考场名称',maxlength:80,full:true,placeholder:'按外部预约通知填写'},
    {name:'booking_reference',label:'预约凭证编号或通知摘要',maxlength:120,full:true,help:'填写预约成功通知中的编号，或用于核对的通知信息。'}
  ],v=>mutate('exams','POST',{subject_id:+id,...v},'考试信息已登记，等待管理员核对'),{description:'请先在交管渠道完成预约，再如实填写通知内容。本系统不负责预约或组织考试。',submit:'提交登记'});break;
  case 'cancel-exam':confirmAction('撤回考试登记','只撤回本系统中的登记。外部考试登记不会因此取消，请按交管渠道的流程另行处理。',()=>mutate('exams/'+id,'PATCH',{action:'cancel'},'本系统登记已撤回'),true);break;
  case 'verify-exam':{const e=state.exams.find(x=>x.id===+id);showForm('核对考试信息',[],()=>mutate('exams/'+id,'PATCH',{action:'verify'},'已核对考试信息，可据此安排练习'),{description:e.exam_date+' '+e.exam_time+'，'+e.location+'。预约凭证：'+e.booking_reference+'。请与学员提供的外部通知核对；如有错误，请退回补充。',submit:'信息一致，确认'});break;}
  case 'return-exam':showForm('退回补充或更正',[{name:'note',label:'需要更正的信息',type:'textarea',maxlength:200,full:true}],v=>mutate('exams/'+id,'PATCH',{action:'return',...v},'已退回，等待学员重新登记'),{description:'此操作只退回本系统登记，不影响外部预约。',submit:'退回补充',danger:true});break;
  case 'result-exam':{const e=state.exams.find(x=>x.id===+id);showForm('同步外部考试结果',[{name:'score',label:'外部考试成绩（分）',type:'number',min:0,max:100,step:1},{name:'result_source',label:'成绩来源',maxlength:120,placeholder:'例如：学员提供的交管考试结果通知'}],v=>mutate('exams/'+id,'PATCH',{action:'record-result',score:+v.score,result_source:v.result_source},'外部考试结果已归档'),{description:'根据学员提供的交管考试结果登记，驾校不进行考试评分。',submit:'保存结果'});break;}
  case 'prep-training':{const e=state.exams.find(x=>x.id===+id);scheduleForm({subject_id:e.subject_id,date:addDay(1),exam_date:e.exam_date,coach_id:user(e.student_id).coach_id});break;}
  case 'theme':setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');if(state)render();break;
  case 'edit-subject':{const s=subject(+id);showForm('修改'+s.name+'规则',[{name:'required_minutes',label:'要求时长（分钟）',type:'number',value:s.required_minutes,min:1,max:60000,step:1,help:'60 分钟 = 1 小时'},{name:'pass_score',label:'成绩通过线（分）',type:'number',value:s.pass_score,min:1,max:100,step:1}],v=>mutate('subjects/'+id,'PATCH',{required_minutes:+v.required_minutes,pass_score:+v.pass_score},'科目规则已更新'));break;}
  case 'export-hours':exportHours();break;
}}

document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;try{await handleAction(button.dataset.action,button.dataset.id,button);}catch(e){toast(e.message,true);if(e.status===401){closeModal();login();}}});
document.addEventListener('submit',async event=>{
  const form=event.target;if(!['login-form','filters','modal-form','profile-form'].includes(form.id))return;event.preventDefault();
  const values=Object.fromEntries(new FormData(form));if(form.id==='filters'){filters[route]=values;render();return;}
  const submit=$('[type="submit"]',form),error=$('.form-error',form),original=submit.innerHTML;submit.disabled=true;submit.textContent='正在提交…';error.classList.remove('visible');
  try{
    if(form.id==='login-form'){await api('login',{method:'POST',body:values});history.replaceState(null,'','#/');await refresh();toast('登录成功');}
    if(form.id==='modal-form'&&modalSubmit)await modalSubmit(values);
    if(form.id==='profile-form'){await api('profile',{method:'PATCH',body:values});await refresh();toast('个人资料已保存');}
  }catch(e){error.textContent=e.message;error.classList.add('visible');if(e.status===401&&form.id!=='login-form'){closeModal();login();toast('登录已失效，请重新登录',true);}}
  finally{if(submit.isConnected){submit.disabled=false;submit.innerHTML=original;}}
});
modal.addEventListener('click',e=>{if(e.target===modal){const rect=modal.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal();}});
modal.addEventListener('cancel',e=>{e.preventDefault();closeModal();});
window.addEventListener('hashchange',()=>{if(modal.open)closeModal();if(state)render();});
document.addEventListener('input',e=>{if(e.target.closest('#profile-form'))profileDirty=true;});
window.addEventListener('focus',async()=>{if(state&&!modal.open&&!refreshing&&!profileDirty){refreshing=true;try{await refresh();}catch(e){if(e.status===401)login();}finally{refreshing=false;}}});
try{await refresh();}catch(e){if(e.status!==401)toast('暂时无法连接服务，请稍后刷新页面。',true);login();}

function enhanceSurfaces(){
  for(const panel of app.querySelectorAll('.paper,.resource-card,.exam-card,.schedule-card')){
    if(panel.parentElement.classList.contains('surface-shell'))continue;
    const shell=document.createElement('div');shell.className='surface-shell';
    panel.before(shell);shell.append(panel);
  }
  for(const button of app.querySelectorAll('.btn')){
    const arrow=button.querySelector('svg');
    if(arrow&&button.lastElementChild===arrow){const well=document.createElement('span');well.className='button-well';arrow.before(well);well.append(arrow);}
  }
}
function setTheme(value){document.documentElement.dataset.theme=value;localStorage.setItem('qicheng-theme',value);}
